workflow_yaml:
name: dry-run
jobs:
  fetch:
    name: Fetch record
    adaptor: '@openfn/language-dhis2@latest'
    body: |
      get('users', { fields: 'id,firstName,surname,email,phoneNumber,birthday,userCredentials[username]', order: 'created:desc', pageSize: 1 });
  post:
    name: Post record
    adaptor: '@openfn/language-openmrs@latest'
    body: |
      fn(state => {
        const u = state.data.users[0];
        state.user = {
          username: u.userCredentials.username,
          password: 'Openmrs123!',
          person: { names: [{ givenName: u.firstName, familyName: u.surname }], gender: 'U', birthdate: new Date().toISOString().slice(0, 10) },
          roles: ['Provider'],
        };
        return state;
      });
      create('user', state => state.user);
triggers:
  webhook:
    type: webhook
edges:
  webhook->fetch:
    source_trigger: webhook
    target_job: fetch
  fetch->post:
    source_job: fetch
    target_job: post
    condition_type: on_job_success
